	 */
	public static function doInsert($values, PropelPDO $con = null)
	{

    foreach (sfMixer::getCallables('BaseTbrh099EgresoPeer:doInsert:pre') as $callable)
    {
      $ret = call_user_func($callable, 'BaseTbrh099EgresoPeer', $values, $con);
      if (false !== $ret)
      {
        return $ret;
      }
    }


		if ($con === null) {
			$con = Propel::getConnection(Tbrh099EgresoPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
		}

		if ($values instanceof Criteria) {
			$criteria = clone $values; // rename for clarity
		} else {
			$criteria = $values->buildCriteria(); // build Criteria from Tbrh099Egreso object
		}

		if ($criteria->containsKey(Tbrh099EgresoPeer::CO_EGRESO) && $criteria->keyContainsValue(Tbrh099EgresoPeer::CO_EGRESO) ) {
			throw new PropelException('Cannot insert a value for auto-increment primary key ('.Tbrh099EgresoPeer::CO_EGRESO.')');
		}


		// Set the correct dbName
		$criteria->setDbName(self::DATABASE_NAME);

		try {
			// use transaction because $criteria could contain info
			// for more than one table (I guess, conceivably)
			$con->beginTransaction();
			$pk = BasePeer::doInsert($criteria, $con);
			$con->commit();
		} catch(PropelException $e) {
			$con->rollBack();
			throw $e;
		}

		
    foreach (sfMixer::getCallables('BaseTbrh099EgresoPeer:doInsert:post') as $callable)
    {
      call_user_func($callable, 'BaseTbrh099EgresoPeer', $values, $con, $pk);
    }

    return $pk;
