	 *
	 * @param      string $pk the primary key.
	 * @param      PropelPDO $con the connection to use
	 * @return     Tbrh099Egreso
	 */
	public static function retrieveByPK($pk, PropelPDO $con = null)
	{

		if (null !== ($obj = Tbrh099EgresoPeer::getInstanceFromPool((string) $pk))) {
			return $obj;
		}

		if ($con === null) {
			$con = Propel::getConnection(Tbrh099EgresoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
		}

		$criteria = new Criteria(Tbrh099EgresoPeer::DATABASE_NAME);
		$criteria->add(Tbrh099EgresoPeer::CO_EGRESO, $pk);

		$v = Tbrh099EgresoPeer::doSelect($criteria, $con);

		return !empty($v) > 0 ? $v[0] : null;
	}

